$dest = "E:\grid\data\sources\FL_2025_tax_rolls"
New-Item -ItemType Directory -Force -Path $dest | Out-Null

$total = $urls.Count
$done = 0
foreach ($url in $urls) {
    $filename = [System.Uri]::UnescapeDataString(([Uri]$url).Segments[-1])
    $outPath = Join-Path $dest $filename
    $done++
    if (Test-Path $outPath) {
        Write-Host "[$done/$total] SKIP (exists): $filename"
        continue
    }
    Write-Host "[$done/$total] Downloading: $filename"
    try {
        Invoke-WebRequest -Uri $url -OutFile $outPath -ErrorAction Stop
        $size = [math]::Round((Get-Item $outPath).Length/1KB, 1)
        Write-Host "  OK: ${size}KB"
    } catch {
        Write-Host "  FAILED: $_"
    }
}
Write-Host "Done. Files in: $dest"
